source(file.path(commandArgs(TRUE)[1],'code/common.R'))
complete<-all(file.exists(file.path(out,paste0(c('l00','l02','l08'),'_complete.json'))));if(file.exists(file.path(out,'input_check.json'))&&(complete||file.exists(file.path(out,'tmp/hvg_input.rds'))))quit(save='no')
